    23	      return { status: 201 };
    24	    },
    25	
    26	    async deleteRepo(req: Request) {
    27	      try {
    28	        await store.deleteRepo(req.params.id, req.user);
    29	        return { status: 204 };
    30	      } catch {
    31	        return { status: 404 };
    32	      }
    33	    },
    34	
    35	    async template(req: Request) {
    36	      const base = path.join(REPOS_DIR, req.params.id);
    37	      const file = path.resolve(base, "docs", req.params.name);
    38	      if (!file.startsWith(base)) return { status: 400 };
    39	      return { status: 200, body: await readFile(file, "utf8") };
    40	    },
    41	
    42	    async auditLog(req: Request) {
    43	      if (!isAdminAddress(req.ip)) return { status: 403 };
    44	      return { status: 200, body: await readFile(AUDIT_LOG, "utf8") };
    45	    },
    46	
    47	    async issue(req: Request) {
    48	      return { status: 200, body: await getIssue(req.params.key) };
    49	    },
    50	
    51	    async build(req: Request) {
    52	      return { status: 200, body: await getBuild(req.params.id) };
    53	    },
    54	
    55	    async assignedIssues(req: Request) {
    56	      return { status: 200, body: await searchAssigned(req.body.email) };
    57	    },
    58	
    59	    async cacheListing(req: Request) {
    60	      const dir = cachePath(req.params.id);
    61	      return { status: 200, body: await readFile(path.join(dir, "INDEX"), "utf8") };
    62	    },
    63	  };
    64	}
