     3	export interface Db {
     4	  query(sql: string, params: unknown[]): Promise<Repo[]>;
     5	  run(sql: string, params: unknown[]): Promise<{ changes: number }>;
     6	}
     7	
     8	export interface UserContext {
     9	  oid: string;
    10	  isAdmin: boolean;
    11	}
    12	
    13	export class Store {
    14	  constructor(private db: Db) {}
    15	
    16	  async insertRepo(repo: Repo): Promise<void> {
    17	    await this.db.run("INSERT INTO repos (id, remote_url, owner) VALUES (?, ?, ?)", [repo.id, repo.remoteUrl, repo.owner]);
    18	  }
    19	
    20	  async findByName(name: string): Promise<Repo[]> {
    21	    return this.db.query("SELECT * FROM repos WHERE name = ?", [name]);
    22	  }
    23	
    24	  async deleteRepo(id: string, ctx: UserContext): Promise<void> {
    25	    if (ctx.isAdmin) {
    26	      await this.db.run("DELETE FROM repos WHERE id = ?", [id]);
    27	      return;
    28	    }
    29	    const result = await this.db.run("DELETE FROM repos WHERE id = ? AND (owner = ? OR owner = 'system')", [id, ctx.oid]);
    30	    if (result.changes === 0) throw new Error(`repo not found: ${id}`);
    31	  }
    32	}

